  // 1. Every building becomes two wall events.
  const events = [];
  for (const [left, right, height] of buildings) {
    events.push([left,  height, 'up'  ]);
    events.push([right, height, 'down']);
  }

  // 2. Sort by x. Ties: ups before downs, taller ups
  //    first, shorter downs first — negating the height
  //    of every 'up' encodes all three rules at once.
  events.sort((a, b) =>
    a[0] - b[0] ||
    (a[2] === 'up' ? -a[1] : a[1]) -
    (b[2] === 'up' ? -b[1] : b[1]));

  // 3. Sweep left to right, tracking what still stands.
  const active = [0];              // ground never ends
  const corners = [];
  for (const [x, height, type] of events) {
    if (type === 'up') active.push(height);
    else active.splice(active.indexOf(height), 1);

    const top = Math.max(...active);
    const prev = corners[corners.length - 1];
    if (prev === undefined || prev[1] !== top) {
      corners.push([x, top]);      // the outline changed
    }
  }
  return corners;
