  // Sort a COPY by start — the caller's pile is not ours
  // to scramble.
  const sorted = [...intervals].sort((a, b) => a[0] - b[0]);

  const merged = [];

  for (const [start, end] of sorted) {
    const lastIndex = merged.length - 1;
    const last = merged[lastIndex];

    // In start order, the only run this block can touch is
    // the LAST one in the answer. Starting exactly where
    // that one ends still counts as touching.
    const overlapsLast = last !== undefined && start <= last[1];
    if (overlapsLast) {
      merged[lastIndex] = [last[0], Math.max(last[1], end)];
    } else {
      merged.push([start, end]);
    }
  }

