  const uf = new UnionFind();
  const nameOf = new Map();          // email → the name on its record

  // PHASE 1 — tie every record's emails to that record's first one.
  for (const [name, ...emails] of accounts) {
    const firstEmail = emails[0];    // the record's anchor
    for (const email of emails) {
      nameOf.set(email, name);
      uf.union(firstEmail, email);   // one record = one group
    }
  }

  // PHASE 2 — every email asks its leader; same leader, same person.
  const groups = new Map();          // leader email → its emails
  for (const email of nameOf.keys()) {
    const root = uf.find(email);
    groups.set(root, [...(groups.get(root) ?? []), email]);
  }

  // PHASE 3 — one row per leader, that person's emails sorted.
  const merged = [];
  for (const [root, emails] of groups) {
    const name = nameOf.get(root);   // any email carries the person's name
    merged.push([name, ...[...emails].sort()]);
  }
  return merged;
