  // Sort a COPY by FINISH time — that is the whole trick.
  // Of two requests that clash, the earlier finisher frees
  // the room sooner, so it blocks the least future.
  const sorted = [...intervals].sort((a, b) => a[1] - b[1]);

  let removed = 0;
  let fence = -Infinity;  // where the last KEPT request ended

  for (const [start, end] of sorted) {
    // "At or after": starting exactly when the last kept one
    // ended is fine, because the endpoints only touch.
    const fitsAfterTheLastKept = start >= fence;

    if (fitsAfterTheLastKept) {
      fence = end;        // keep it — the fence moves to its end
    } else {
      removed += 1;       // collides with a kept one — cancel it
    }
  }
  return removed;
