  // An empty spot breaks no rule, so it passes — and
  // that is what stops the recursion.
  if (node === null) {
    return true;
  }

  // STRICTLY inside: a value equal to the floor or the
  // ceiling would be filed on the wrong side of the
  // ancestor that set it.
  const insideInheritedRange = node.val > low && node.val < high;
  if (!insideInheritedRange) {
    return false;   // this node breaks the rule
  }

  // Going left lowers the ceiling to this value; going
  // right raises the floor to it.
  const leftPasses = isValidBST(node.left, low, node.val);
  if (!leftPasses) {
    return false;   // a descendant broke the rule
  }
  return isValidBST(node.right, node.val, high);
