  // Lay the tickets end to end: weights 1, 3, 6 become
  // running totals 1, 4, 10 — each chunk as wide as
  // its weight, so heavy items cover more of the line.
  const runningTotals = [];
  let total = 0;
  for (const weight of weights) {
    total += weight;
    runningTotals.push(total);
  }

  return function pick(roll) {
    const target = roll * total;   // roll is uniform in [0, 1)

    // Find the FIRST running total STRICTLY bigger than
    // the dart. Invariant: the answer lives in lo..hi —
    // everything under lo is proved too small, and hi is
    // always still a live candidate.
    let lo = 0;
    let hi = runningTotals.length - 1;
    while (lo < hi) {
      const mid = Math.floor((lo + hi) / 2);
      const totalAtMid = runningTotals[mid];
      const midIsTooSmall = totalAtMid <= target;
      if (midIsTooSmall) {
        lo = mid + 1;    // mid's chunk ends at or before the dart
      } else {
        hi = mid;        // mid might BE the answer — keep it
      }
    }

    return lo;   // lo === hi, and the invariant says that is the chunk
  };
