  // tails[k] = the SMALLEST number an increasing run
  // of length k+1 can end on. Not a subsequence —
  // a best-possible-endings ledger, one row per length.
  const tails = [];

  for (const num of nums) {
    // Binary search the pile tops (already sorted)
    // for the first one that is >= num.
    let lo = 0;
    let hi = tails.length;
    while (lo < hi) {
      const mid = Math.floor((lo + hi) / 2);
      if (tails[mid] < num) {
        lo = mid + 1;      // too small — look right
      } else {
        hi = mid;          // works — but look left too
      }
    }

    if (lo === tails.length) {
      tails.push(num);     // taller than every top: NEW pile
    } else {
      tails[lo] = num;     // that length can now end lower
    }
  }
  return tails.length;     // the PILE COUNT is the answer
