  // Infinity marks "no combination reaches this
  // amount" — and Infinity + 1 is still Infinity,
  // so an impossible amount can never win below.
  const dp = new Array(amount + 1).fill(Infinity);
  dp[0] = 0;               // making nothing takes no coins

  // Left to right: by the time we compute \`a\`, every
  // smaller amount already holds its final answer.
  for (let a = 1; a <= amount; a++) {
    for (const coin of coins) {
      const remainder = a - coin;
      if (remainder >= 0) {
        // "if this coin went in last, the rest is
        //  an amount I already solved"
        const withThisCoin = dp[remainder] + 1;
        if (withThisCoin < dp[a]) {
          dp[a] = withThisCoin;
        }
      }
    }
  }

  if (dp[amount] === Infinity) {
    return -1;             // the coins cannot make it
  }
  return dp[amount];
