  // Two runners leave the same car: the tortoise takes one
  // link per turn, the hare two. Floyd's tortoise and hare.
  let tortoise = head;
  let hare = head;

  // The hare needs two links in front of it to move, so this
  // IS the end-of-track test — nothing measured, nothing marked.
  while (hare !== null && hare.next !== null) {
    tortoise = tortoise.next;   // one car
    hare = hare.next.next;      // two cars

    // On a loop the hare comes up from BEHIND and closes the
    // gap by exactly one per turn, so it cannot hurdle past.
    if (tortoise === hare) {
      return true;
    }
  }

  // A car with nothing behind it: the track ends.
  return false;
