function bindIndex(group, enter, update, exit, data) {
  let i = 0, node;
  for (; i < data.length; ++i) {
    if (node = group[i]) {
      node.__data__ = data[i];   // node i shows datum i, whoever it is
      update[i] = node;
    } else {
      enter[i] = {__data__: data[i]};   // d3: new EnterNode(parent, …)
    }
  }
  for (; i < group.length; ++i) {
    if (node = group[i]) exit[i] = node;
  }
}

function bindKey(group, enter, update, exit, data, key) {
  const nodeByKeyValue = new Map();
  const keyValues = new Array(group.length);
  let i, node, keyValue;
  // Key every old node. (d3 sends a node with a repeated key to exit.)
  for (i = 0; i < group.length; ++i) {
    node = group[i];
    keyValues[i] = keyValue = key(node.__data__) + "";
    nodeByKeyValue.set(keyValue, node);
  }
  // Key every datum, and claim the node with the same key, if any.
  for (i = 0; i < data.length; ++i) {
    keyValue = key(data[i]) + "";
    if (node = nodeByKeyValue.get(keyValue)) {
      update[i] = node;
      node.__data__ = data[i];
      nodeByKeyValue.delete(keyValue);
    } else {
      enter[i] = {__data__: data[i]};   // no old node has this key
    }
  }
  // Nodes nobody claimed leave.
  for (i = 0; i < group.length; ++i) {
    if ((node = group[i]) && (nodeByKeyValue.get(keyValues[i]) === node)) {
      exit[i] = node;
    }
  }
}

