const values = [3.1, 4.7, 2.2, 5.5, 4.1, 6.8, 3.9, 1.2, 5.1, 4.4,
  7.3, 2.9, 4.9, 5.8, 3.3, 6.1, 4.2, 9, 5.3, 2.6, 4.6, 3.7, 6.4, 5];
