// each takes an iterable and returns a new, lazy one.
function* naturals() {
  let n = 1;
  while (true) {         // infinite: safe only because lazy
    yield n;
    n += 1;
  }
}

function* filter(predicate, iterable) {
  for (const item of iterable) {   // may pull many
    if (predicate(item)) {
      yield item;   // passed the test
    }
  }
}

